          { source, args: input.args, parentSessionID: tc.sessionID },
          {
            background: input.background === true,
            ...(input.background === true ? {} : { signal: tc.signal }),
            ...(toIsolation(input.isolation) ? { isolation: toIsolation(input.isolation) } : {}),
