=> service.info()),
    listRuns: (input, c) => guard(c.error as never, async () => ({ runs: await service.listRuns(input) })),
    getRun: (input, c) => guard(c.error as never, async () => (await serviceForRun(input.runId)).getRun(input.runId)),
    getUnit: (input, c) =>
      guard(c.error as never, async () => ({
        unit: await (await serviceForRun(input.runId)).getUnit(input.runId, input.unitId),
      })),
    getResult: (input, c) =>
      guard(c.error as never, async () => (await serviceForRun(input.runId)).getResult(input.runId)),
    getTranscript: (input, c) =>
      guard(c.error as never, async () =>
        (await serviceForRun(input.runId)).getTranscript(input.runId, input.unitId, {
          whole: input.whole === true,
        }),
      ),
    getActivity: (input, c) =>
      guard(c.error as never, async () => ({
        entries: await (await serviceForRun(input.runId)).getActivity(input.runId),
      })),
    listWorkflows: (_input, c) => guard(c.error as never, () => service.listWorkflows()),
    startRun: (input, c) =>
      guard(c.error as never, async () => {
        const started = await service.startRun(input, { background: true, surface: "the TUI" })
        return { runId: started.runId }
      }),
    stopRun: (input, c) =>
      guard(c.error as never, async () => {
        ;(await serviceForRun(input.runId)).stopRun(input.runId)
        return { ok: true as const }
      }),
    stopUnit: (input, c) =>
      guard(c.error as never, async () => {
        ;(await serviceForRun(input.runId)).stopUnit(input.runId, input.unitId)
        return { ok: true as const }
      }),
    restartUnit: (input, c) =>
      guard(c.error as never, async () => {
        await (await serviceForRun(input.runId)).restartUnit(input.runId, input.unitId)
        return { ok: true as const }
      }),
    resumeRun: (input, c) =>
      guard(c.error as never, async () => ({
        runId: (
          await (
            await serviceForRun(input.runId)
          ).resumeRun(input.runId, input.rerunFailed ?? true, {
            background: true,
            surface: "the TUI",
          })
        ).runId,
      })),
    replyInteraction: (input, c) =>
      guard(c.error as never, async () => {
        await (await serviceForRun(input.runId)).replyInteraction(input.runId, input.interactionId, input.answers)
        return { ok: true as const }
      }),
    cancelInteraction: (input, c) =>
      guard(c.error as never, async () => {
        await (await serviceForRun(input.runId)).cancelInteraction(input.runId, input.interactionId)
        return { ok: true as const }
      }),
    saveRun: (input, c) =>
      guard(c.error as never, async () => (await serviceForRun(input.runId)).saveRun(input.runId, input.name)),
    cleanupRun: (input, c) =>
      guard(c.error as never, async () =>
        (await serviceForRun(input.runId)).cleanupRun(input.runId, input.deleted ?? []),
      ),
    attach: (input, c) =>
      guard(
        c.error as never,
        () => (service.attach(input.surface, input.ttlMs, input.sessionID), { ok: true as const }),
      ),
    detach: (input, c) => guard(c.error as never, () => (service.detach(input.surface), { ok: true as const })),
    eventsSince: (input, c) => guard(c.error as never, () => service.eventsSince(input.after ?? 0, input.epoch)),
    pair: (_input, c) =>
      guard(c.error as never, () => {
        const current = engineGlobal().singletons.get("gateway") as GatewayHandle | undefined
        if (!current)
          throw new WorkflowProtocolError("unsupported", "The Gateway is not running (gateway.enabled: false).")
        return current.createPairingCode()
      }),
  })
  const unsubscribeRpc = service.deps.store.subscribe((event: ProtocolEvent) => {
    if (!alive) return
    void rpc.events.emit("event", elideEvent(event) as never).catch(() => {})
  })

  // --------------------------------------------------------------------------------------------------------------
  // Commands: /workflow and one per durable Workflow, reloaded when Workflow files change
  // --------------------------------------------------------------------------------------------------------------

  let commands: Array<{ name: string; description: string; template: string }> = []
  const refreshCommands = async () => {
    try {
      const listing = await service.listWorkflows()
      commands = listing.workflows.map((entry) => ({
        name: entry.key.replaceAll(":", "/"),
        description: `Workflow: ${entry.description}`,
        template: [
          `**${entry.key}** — ${entry.description}`,
          ...(entry.whenToUse ? [`_${entry.whenToUse}_`] : []),
          "",
          `Run it by calling \`workflow({ name: ${JSON.stringify(entry.key)}, args })\`, building \`args\` from the request below.`,
          `Args JSON Schema: ${entry.args ? JSON.stringify(entry.args) : "(none)"}`,
          "",
          "**Request:** $ARGUMENTS",
        ].join("\n"),
      }))
    } catch {
      commands = []
    }
  }
  await refreshCommands()
  const promptWith =
    (template: string) =>
    async (invocation: { sessionID: string; prompt: { text: string }; delivery: "steer" | "queue" }) => {
      await ctx.session.prompt({
        ...(invocation.prompt as object),
        sessionID: invocation.sessionID,
        text: template.replaceAll("$ARGUMENTS", invocation.prompt.text ?? ""),
        delivery: invocation.delivery,
      } as never)
    }
  await ctx.command.transform((editor) => {
    editor.add({
      name: "workflow",
      description: "Run a durable Workflow by key: /workflow <key> <request>",
      execute: promptWith(WORKFLOW_COMMAND_TEMPLATE) as never,
    })
    const reserved = new Set(["workflow", "workflows"])
    for (const command of commands) {
      if (reserved.has(command.name)) continue
      editor.add({
        name: command.name,
        description: command.description,
        execute: promptWith(command.template) as never,
      })
    }
  })

  const watchers: FSWatcher[] = []
  let reloadTimer: ReturnType<typeof setTimeout> | null = null
  const scheduleReload = () => {
    if (reloadTimer) clearTimeout(reloadTimer)
    reloadTimer = setTimeout(() => {
      void refreshCommands()
        .then(() => (alive ? ctx.command.reload() : undefined))
        .catch(() => {})
    }, 300)
  }
  for (const scope of configDirs(location)) {
    for (const folder of ["workflows", "workflow"]) {
      try {
        const watcher = watch(path.join(scope, folder), { recursive: true }, (_event, file) => {
          if (typeof file === "string" && (file.startsWith("runs") || !file.endsWith(".ts"))) return
          scheduleReload()
        })
        watcher.on("error", () => {})
        watchers.push(watcher)
      } catch {
        // No such folder in this scope.
      }
    }
  }

  // --------------------------------------------------------------------------------------------------------------
  // Gateway
  // --------------------------------------------------------------------------------------------------------------

  const gateway = config.gateway.enabled
    ? await ensureGateway(config.gateway).catch((error: unknown) => {
        console.warn(`[workflow] gateway did not start: ${error instanceof Error ? error.message : String(error)}`)
        return null
      })
    : null
  const unregisterGateway = gateway?.register(location, service) ?? (() => {})

  return async () => {
    alive = false
    resolveDisposed()
    events.abort()
    unsubscribeRpc()
    unregisterGateway()
    if (reloadTimer) clearTimeout(reloadTimer)
    for (const watcher of watchers) watcher.close()
    // Only the current owner hands the location back: a leaked older instance cleaning up late must not unhook
    // the instance that replaced it.
    const locationState = locationSlot(location)
    if (locationState.owner === instance) {
      locationState.owner = null
      slot.replyPermission = async () => {
        throw new Error("no plugin instance is serving this location")
      }
    }
  }
}

export const WorkflowPlugin = Plugin.define({ id: PLUGIN_ID, setup })

export { argsSchemaOf }

/**
 * Workflow protocol v1 — the stable, versioned contract every surface speaks.
 *
 * One source of truth: these zod schemas produce the TypeScript types, the RPC contract (`../service/rpc.ts`),
 * the Gateway's request validation, and the published JSON Schemas (`docs/protocol/schemas/`, generated by
 * `script/protocol-schemas.ts`). Within v1 changes are additive only: new optional fields, new event types,
 * new error codes. A breaking change creates v2.
 *
 * Client rule (see docs/protocol/README.md): snapshot → subscribe → apply events whose `revision` is greater
 * than the snapshot's → on a gap, or on `resync.required`, re-read the snapshot.
 */
import { z } from "zod"

export const PROTOCOL_VERSION = 1 as const

// ---------------------------------------------------------------------------------------------------------------
// Shared pieces
// ---------------------------------------------------------------------------------------------------------------

export const Usage = z.object({
  tokens: z.object({
    input: z.number(),
    output: z.number(),
    reasoning: z.number(),
    cacheRead: z.number(),
    cacheWrite: z.number(),
  }),
  /** USD, as reported by OpenCode for the Unit sessions. */
  cost: z.number(),
})
export type Usage = z.infer<typeof Usage>

export function emptyUsage(): Usage {
  return { tokens: { input: 0, output: 0, reasoning: 0, cacheRead: 0, cacheWrite: 0 }, cost: 0 }
}

export function addUsage(into: Usage, add: Usage): Usage {
  return {
    tokens: {
      input: into.tokens.input + add.tokens.input,
      output: into.tokens.output + add.tokens.output,
      reasoning: into.tokens.reasoning + add.tokens.reasoning,
      cacheRead: into.tokens.cacheRead + add.tokens.cacheRead,
      cacheWrite: into.tokens.cacheWrite + add.tokens.cacheWrite,
    },
    cost: into.cost + add.cost,
  }
}

export const WorkflowErrorRecord = z.object({
  unit: z.string(),
  prompt: z.string(),
  subagent: z.string(),
  error: z.string(),
})
export type WorkflowErrorRecord = z.infer<typeof WorkflowErrorRecord>

export const ProtocolError = z.object({
  code: z.enum([
    "not_found",
    "conflict",
    "invalid_args",
    "invalid_state",
    "unauthorized",
    "forbidden",
    "rate_limited",
    "unsupported",
    "internal",
  ]),
  message: z.string(),
  retryable: z.boolean(),
  details: z.record(z.string(), z.unknown()).optional(),
})
export type ProtocolError = z.infer<typeof ProtocolError>
export type ProtocolErrorCode = ProtocolError["code"]

export class WorkflowProtocolError extends Error {
  readonly code: ProtocolErrorCode
  readonly retryable: boolean
  readonly details?: Record<string, unknown>
  constructor(
    code: ProtocolErrorCode,
    message: string,
    options: { retryable?: boolean; details?: Record<string, unknown> } = {},
  ) {
    super(message)
    this.name = "WorkflowProtocolError"
    this.code = code
    this.retryable = options.retryable ?? false
    this.details = options.details
  }
  toJSON(): ProtocolError {
    return {
      code: this.code,
      message: this.message,
      retryable: this.retryable,
      ...(this.details ? { details: this.details } : {}),
    }
  }
}

